// ============================================================
// TutorBot · Modulo COORDINACION
// Menu exclusivo del rol coordinacion. Por ahora una sola opcion:
// reporte de tutorias por materia de la SEMANA ACTUAL.
//
// El rol se valida DOS veces a proposito: el contexto ya comprobo el
// telegram_user contra Config, y aqui se vuelve a comprobar. Un modulo que
// entrega datos agregados de toda la operacion no debe confiar en que alguien
// mas hizo la verificacion.
//
// Semana actual = lunes a domingo que contiene la fecha de hoy, en la zona
// horaria de la institucion. Se filtra por TUTORIAS.fecha (cuando ocurre la
// tutoria), no por fecha_solicitud: la pregunta es que se dicto esta semana.
// ============================================================
const ctx = $input.first().json;
const cfg = $('Config').first().json;

const REALIZADAS = ['ASIGNADA', 'CONFIRMADA', 'FINALIZADA'];  // ocurrieron o estan en pie
const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const arriba = s => String(s == null ? '' : s).toUpperCase().trim();
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function sesion(pantalla, paso, datos) {
  return {
    telegram_user: ctx.telegram_user,
    pantalla_actual: pantalla,
    paso_actual: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    actualizado_en: cfg.ahora_iso
  };
}
function salida(o) {
  return [{ json: Object.assign({
    telegram_user: ctx.telegram_user,
    chat_id: ctx.chat_id,
    ruta: 'COORDINACION',
    submodo: ctx.submodo,
    accion: 'sin_accion',
    estudiante_row: null,
    tutoria_row: null,
    notificar: null,
    evento: 'coordinacion',
    detalle: ''
  }, o) }];
}

// ------------------------------------------------------------
// Autorizacion
// ------------------------------------------------------------
const yo = String(ctx.telegram_user || '').replace(/[^0-9]/g, '');
const coordinador = filas('Leer COORDINACION').find(c =>
  String(c.telegram_user || '').replace(/[^0-9]/g, '') === yo && yo !== '' &&
  String(c.estado || 'Activo').toLowerCase() === 'activo') || null;

if (!coordinador) {
  return salida({
    mensaje: 'Este menu es solo para la coordinacion academica.',
    sesion: sesion('MENU', 0, {}),
    evento: 'coordinacion_no_autorizada',
    detalle: 'intento de ' + ctx.telegram_user
  });
}

const MENU = [
  'COORDINACION ACADEMICA',
  '',
  '1) Resumen semanal por materia',
  '2) Consultar una materia',
  '',
  'Responde con el numero de la opcion.'
].join('\n');

// ------------------------------------------------------------
// Semana actual: lunes a domingo
// ------------------------------------------------------------
const ph = String(cfg.hoy).split('-').map(Number);
const hoyUTC = Date.UTC(ph[0], ph[1] - 1, ph[2]);
const dow = new Date(hoyUTC).getUTCDay();              // 0 domingo ... 6 sabado
const desdeLunes = dow === 0 ? 6 : dow - 1;            // lunes como primer dia
const lunes = new Date(hoyUTC - desdeLunes * 86400000).toISOString().slice(0, 10);
const domingo = new Date(hoyUTC + (6 - desdeLunes) * 86400000).toISOString().slice(0, 10);

const tutorias = filas('Leer TUTORIAS').filter(t => String(t.id_tutoria || '') !== '');
const semana = tutorias.filter(t => {
  const f = String(t.fecha || '').slice(0, 10);
  return f >= lunes && f <= domingo;
});

// ------------------------------------------------------------
// Agrupacion por materia (requisito 2)
// ------------------------------------------------------------
const grupos = new Map();   // norm(materia) -> agregado
for (const t of semana) {
  const nombre = String(t.materia || 'Sin materia').trim() || 'Sin materia';
  const k = norm(nombre);
  if (!grupos.has(k)) {
    grupos.set(k, { materia: nombre, cantidad: 0, finalizadas: 0, programadas: 0,
                    canceladas: 0, sin_cupo: 0, tutores: new Map() });
  }
  const a = grupos.get(k);
  const e = arriba(t.estado);
  if (e === 'FINALIZADA') { a.finalizadas++; a.cantidad++; }
  else if (REALIZADAS.includes(e)) { a.programadas++; a.cantidad++; }
  else if (e === 'CANCELADA') a.canceladas++;
  else if (e === 'SIN_DISPONIBILIDAD') a.sin_cupo++;

  const quien = String(t.nombre_tutor || '').trim();
  if (quien && REALIZADAS.includes(e)) a.tutores.set(quien, (a.tutores.get(quien) || 0) + 1);
}

// Solo entran al listado las materias que tuvieron tutorias reales
const lista = Array.from(grupos.values())
  .filter(a => a.cantidad > 0)
  .sort((x, y) => y.cantidad - x.cantidad || x.materia.localeCompare(y.materia, 'es'));

const TOTAL = lista.reduce((s, a) => s + a.cantidad, 0);

// Icono por familia de materia, para que el mensaje se lea como el formato pedido
function icono(materia) {
  const m = norm(materia);
  if (/matem|calculo|algebra|estadis|geometr|aritmet/.test(m)) return '\u{1F9EE}';   // abaco
  if (/program|software|bases de datos|algoritm|computac|redes/.test(m)) return '\u{1F4BB}'; // laptop
  if (/quimic/.test(m)) return '\u{1F9EA}';                                          // tubo de ensayo
  if (/fisica|termodinam|mecanic/.test(m)) return '\u2699\uFE0F';                     // engranaje
  if (/contab|financ|economi|administrac/.test(m)) return '\u{1F4B0}';                // bolsa
  if (/biolog|anatom/.test(m)) return '\u{1F9EC}';                                    // adn
  return '\u{1F4D8}';                                                                 // libro
}

const cabecera = [
  '\u{1F4DA} Resumen de Tutorias por Materia',
  'Semana del ' + lunes + ' al ' + domingo,
  '----------------------------'
].join('\n');

function bloqueTotal(items) {
  const t = items.reduce((s, a) => s + a.cantidad, 0);
  return [
    items.length
      ? items.map(a => icono(a.materia) + ' ' + a.materia + ': ' + a.cantidad).join('\n')
      : '(sin tutorias esta semana)',
    '----------------------------',
    '\u{1F4C8} TOTAL SEMANA: ' + t
  ].join('\n');
}

// ------------------------------------------------------------
// Paso 1 · menu de coordinacion
// ------------------------------------------------------------
if (ctx.submodo === 'menu') {
  return salida({
    mensaje: 'Hola ' + String(coordinador.nombre || '').split(' ')[0] +
             '. Bienvenido al panel de Coordinacion Academica.\n\n' + MENU,
    sesion: sesion('COORD_MENU', 1, {}),
    evento: 'coordinacion_menu'
  });
}

// ------------------------------------------------------------
// Paso 2 · eligio una opcion del menu
// ------------------------------------------------------------
if (ctx.submodo === 'elegir') {
  const m = /^\s*([1-9])\s*[).\-]?\s*$/.exec(String(ctx.texto || '').trim());
  const opcion = m ? m[1] : '';

  if (opcion !== '1' && opcion !== '2') {
    return salida({
      mensaje: 'Esa opcion no existe.\n\n' + MENU,
      sesion: sesion('COORD_MENU', 1, {}),
      evento: 'coordinacion_opcion_invalida',
      detalle: String(ctx.texto || '').slice(0, 40)
    });
  }

  const vacio = cabecera + '\n\n(sin tutorias esta semana)\n----------------------------\n' +
                '\u{1F4C8} TOTAL SEMANA: 0';

  // --- Opcion 1: el resumen completo, en el formato que pidio coordinacion ---
  if (opcion === '1') {
    if (!lista.length) {
      return salida({
        mensaje: vacio + '\n\nNo hubo actividad entre el ' + lunes + ' y el ' + domingo + '.\n\n' + MENU,
        sesion: sesion('COORD_MENU', 1, {}),
        evento: 'reporte_materia_vacio',
        detalle: lunes + '..' + domingo
      });
    }
    return salida({
      mensaje: cabecera + '\n\n' + bloqueTotal(lista) + '\n\n' +
               lista.length + ' materia(s) con actividad.\n\n' + MENU,
      sesion: sesion('COORD_MENU', 1, {}),
      evento: 'reporte_semanal_generado',
      detalle: 'resumen | ' + lunes + '..' + domingo + ' | total ' + TOTAL
    });
  }

  // --- Opcion 2: elegir una materia concreta ---
  if (!lista.length) {
    return salida({
      mensaje: vacio + '\n\nNo hay materias que consultar esta semana.\n\n' + MENU,
      sesion: sesion('COORD_MENU', 1, {}),
      evento: 'reporte_materia_vacio',
      detalle: lunes + '..' + domingo
    });
  }

  return salida({
    mensaje: [
      'Consultar una materia · semana del ' + lunes + ' al ' + domingo,
      '',
      'Que materia quieres ver?',
      '',
      lista.map((a, i) => (i + 1) + ') ' + icono(a.materia) + ' ' + a.materia + ' (' + a.cantidad + ')').join('\n'),
      '',
      'Responde con el numero, o /coordinacion para volver al menu.'
    ].join('\n'),
    sesion: sesion('COORD_MATERIA', 2, { materias: lista.map(a => a.materia), desde: lunes, hasta: domingo }),
    evento: 'reporte_materia_seleccion',
    detalle: lista.length + ' materias con actividad'
  });
}

// ------------------------------------------------------------
// Paso 3 · eligio la materia y se entrega su detalle
// ------------------------------------------------------------
const datos = ctx.datos || {};
const guardadas = Array.isArray(datos.materias) ? datos.materias : lista.map(a => a.materia);
const n = parseInt(String(ctx.texto || '').replace(/[^0-9]/g, ''), 10);

if (isNaN(n) || n < 1 || n > guardadas.length) {
  return salida({
    mensaje: 'Numero fuera de rango. Elige entre 1 y ' + guardadas.length +
             ', o escribe /coordinacion para volver al menu.',
    sesion: sesion('COORD_MATERIA', 2, datos),
    evento: 'reporte_materia_rechazado',
    detalle: String(ctx.texto || '').slice(0, 30)
  });
}

// --- Una materia concreta ---
const elegida = guardadas[n - 1];
const a = grupos.get(norm(elegida));

if (!a) {
  return salida({
    mensaje: 'Esa materia ya no tiene tutorias en la semana actual. Escribe /coordinacion para ver el listado al dia.',
    sesion: sesion('COORD_MENU', 1, {}),
    evento: 'reporte_materia_desfasado',
    detalle: String(elegida)
  });
}

const cargaTutores = Array.from(a.tutores.entries()).sort((x, y) => y[1] - x[1]);
const participacion = TOTAL ? Math.round(a.cantidad / TOTAL * 1000) / 10 : 0;

return salida({
  mensaje: [
    cabecera,
    '',
    icono(a.materia) + ' ' + a.materia + ': ' + a.cantidad,
    '----------------------------',
    '\u{1F4C8} TOTAL SEMANA: ' + TOTAL,
    '',
    'Detalle de ' + a.materia + ':',
    '  Finalizadas: ' + a.finalizadas,
    '  Programadas sin cerrar: ' + a.programadas,
    '  Canceladas: ' + a.canceladas,
    '  Sin cupo: ' + a.sin_cupo,
    '  Participacion en la semana: ' + participacion + '%',
    cargaTutores.length
      ? '  Dictadas por: ' + cargaTutores.map(c => c[0] + ' (' + c[1] + ')').join(', ')
      : '  Sin tutor asignado todavia',
    '',
    MENU
  ].join('\n'),
  sesion: sesion('COORD_MENU', 1, {}),
  evento: 'reporte_materia_generado',
  detalle: a.materia + ' | ' + lunes + '..' + domingo + ' | ' + a.cantidad + ' de ' + TOTAL
});

// ============================================================
// TutorBot · Normalizar respuesta del modulo
// Punto unico de convergencia de los 7 modulos. Garantiza que, sin importar
// que rama se ejecuto, exista siempre: mensaje, sesion, accion y fila de log.
// Hay una copia de este nodo por rama: 'Normalizar REGISTRO', 'Normalizar MENU', etc.
// Los nodos siguientes de cada rama leen del suyo, no de uno compartido.
// ============================================================
const it = $input.first().json;
const cfg = $('Config').first().json;

// ---- Rastro de la IA (si esta ejecucion paso por el interprete) ----
// $('Nodo') lanza error si el nodo no se ejecuto en esta rama: se captura.
// En el sub-workflow el contexto llega por 'Ejecutar modulo'; en un flujo unico
// viene del nodo de validacion. Se prueban los dos y se ignora el que no exista.
let ia = null;
for (const nombre of ['Ejecutar modulo', 'Validar interpretacion IA']) {
  try {
    const j = $(nombre).first().json;
    if (j && j.ia_usada) { ia = j; break; }
  } catch (e) { /* ese nodo no existe en este workflow */ }
}

const ACCIONES = ['sin_accion', 'crear_estudiante', 'crear_tutoria', 'actualizar_tutoria'];
const accion = ACCIONES.includes(it.accion) ? it.accion : 'sin_accion';

// Telegram rechaza mensajes vacios y corta en 4096 caracteres
let mensaje = String(it.mensaje == null ? '' : it.mensaje).trim();
if (!mensaje) mensaje = 'Ocurrio algo inesperado y no pude preparar una respuesta. Escribe /menu para reiniciar.';
// El estudiante debe VER lo que el modelo entendio antes de que se reserve nada
if (ia && ia.ia_aviso) mensaje = ia.ia_aviso + '\n\n' + mensaje;
// Telegram interpreta el texto como HTML: hay que escapar estos tres caracteres.
// Sin esto, un "<" en el texto rompe el envio entero con "can't parse entities".
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
mensaje = esc(mensaje);
if (mensaje.length > 3900) mensaje = mensaje.slice(0, 3900) + '\n\n[mensaje recortado]';

const sesion = it.sesion || {
  telegram_user: it.telegram_user, pantalla_actual: 'MENU', paso_actual: '0',
  datos_parciales: '{}', actualizado_en: cfg.ahora_iso
};

const tutoria = it.tutoria_row || null;
const estudiante = it.estudiante_row || null;

let entidad = 'sesion', id_entidad = String(it.telegram_user || '');
if (tutoria)        { entidad = 'tutoria';    id_entidad = String(tutoria.id_tutoria || ''); }
else if (estudiante){ entidad = 'estudiante'; id_entidad = String(estudiante.id_estudiante || ''); }

// Fila de LOG_EVENTOS: es la trazabilidad que pide la coordinacion
const log = {
  id_evento: 'EV-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 9000 + 1000),
  timestamp: cfg.ahora_iso,
  telegram_user: String(it.telegram_user || ''),
  evento: String(it.evento || 'interaccion'),
  entidad: entidad,
  id_entidad: id_entidad,
  detalle: String(it.detalle == null ? '' : it.detalle).slice(0, 300)
};
// Auditoria del uso de IA: que se le mando, que devolvio y si se acepto
if (ia) {
  log.detalle = (log.detalle + ' | IA:' + ia.ia_intencion +
    '/' + (ia.ia_materia || '-') + '/' + (ia.ia_fecha || '-') +
    ' conf=' + ia.ia_confianza +
    (ia.ia_fallo ? ' descartado=' + ia.ia_fallo : '') +
    ' txt="' + String(ia.ia_texto_original || '').slice(0, 60) + '"').slice(0, 300);
}

return [{
  json: {
    telegram_user: String(it.telegram_user || ''),
    chat_id: String(it.chat_id || ''),
    ruta: it.ruta || '', submodo: it.submodo || '',
    mensaje: mensaje,
    sesion: sesion,
    accion: accion,
    estudiante_row: estudiante,
    tutoria_row: tutoria,
    notificar: it.notificar && it.notificar.chat_id
      ? Object.assign({}, it.notificar, { mensaje: esc(it.notificar.mensaje) })
      : null,
    ia_usada: !!ia,
    ia_fallo: ia ? ia.ia_fallo : '',
    log: log
  }
}];
